//! A tiny re2c-compatible scanner engine.
//!
//! timelib's parsers are generated by re2c, whose semantics are: at the
//! current position, take the *longest* match among all rules; on a tie the
//! rule listed first wins. This module parses re2c-style definitions
//! (`name = expr;` with `"case-sensitive"`, `'case-insensitive'`, `[classes]`,
//! `|`, `*`, `+`, `?`, `{n,m}`), compiles all rules into one Thompson NFA and
//! simulates it to find that match. Input past the end reads as NUL bytes,
//! mirroring re2c's NUL-padded buffer.

use std::collections::HashMap;

/// A set of bytes.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(crate) struct ByteSet([u64; 4]);

impl ByteSet {
    const EMPTY: Self = Self([0; 4]);

    fn insert(&mut self, b: u8) {
        self.0[usize::from(b >> 6)] |= 1 << (b & 63);
    }

    fn contains(self, b: u8) -> bool {
        self.0[usize::from(b >> 6)] & (1 << (b & 63)) != 0
    }

    fn single(b: u8) -> Self {
        let mut s = Self::EMPTY;
        s.insert(b);
        s
    }
}

impl std::fmt::Debug for ByteSet {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ByteSet(..)")
    }
}

/// A regular expression AST node.
#[derive(Debug, Clone)]
pub(crate) enum Node {
    Set(ByteSet),
    Seq(Vec<Node>),
    Alt(Vec<Node>),
    Rep(Box<Node>, u32, Option<u32>),
}

struct ExprParser<'a> {
    s: &'a [u8],
    p: usize,
    defs: &'a HashMap<String, Node>,
}

impl ExprParser<'_> {
    fn skip_ws(&mut self) {
        loop {
            while self.p < self.s.len() && self.s[self.p].is_ascii_whitespace() {
                self.p += 1;
            }
            if self.s.get(self.p..).is_some_and(|r| r.starts_with(b"/*")) {
                let rest = &self.s[self.p + 2..];
                let end = rest.windows(2).position(|w| w == b"*/").map_or(self.s.len(), |e| self.p + 2 + e + 2);
                self.p = end;
                continue;
            }
            break;
        }
    }

    fn peek(&mut self) -> u8 {
        self.skip_ws();
        self.s.get(self.p).copied().unwrap_or(0)
    }

    fn escape(&mut self) -> u8 {
        // Called after a backslash.
        let c = self.s.get(self.p).copied().unwrap_or(0);
        self.p += 1;
        match c {
            b't' => b'\t',
            b'n' => b'\n',
            b'r' => b'\r',
            b'0'..=b'7' => {
                let mut v = u32::from(c - b'0');
                for _ in 0..2 {
                    let d = self.s.get(self.p).copied().unwrap_or(0);
                    if (b'0'..=b'7').contains(&d) {
                        v = v * 8 + u32::from(d - b'0');
                        self.p += 1;
                    }
                }
                u8::try_from(v).unwrap_or(0)
            }
            other => other,
        }
    }

    fn alt(&mut self) -> Node {
        let mut alts = vec![self.seq()];
        while self.peek() == b'|' {
            self.p += 1;
            alts.push(self.seq());
        }
        if alts.len() == 1 {
            alts.pop().unwrap_or(Node::Seq(Vec::new()))
        } else {
            Node::Alt(alts)
        }
    }

    fn seq(&mut self) -> Node {
        let mut items = Vec::new();
        loop {
            let c = self.peek();
            if c == 0 || c == b'|' || c == b')' || c == b';' {
                break;
            }
            items.push(self.postfix());
        }
        if items.len() == 1 {
            items.pop().unwrap_or(Node::Seq(Vec::new()))
        } else {
            Node::Seq(items)
        }
    }

    fn number(&mut self) -> u32 {
        self.skip_ws();
        let mut v = 0;
        while self.p < self.s.len() && self.s[self.p].is_ascii_digit() {
            v = v * 10 + u32::from(self.s[self.p] - b'0');
            self.p += 1;
        }
        v
    }

    fn postfix(&mut self) -> Node {
        let mut node = self.atom();
        loop {
            // Postfix operators bind without intervening whitespace in the
            // sources, but accept it anyway.
            match self.s.get(self.p).copied().unwrap_or(0) {
                b'*' => {
                    self.p += 1;
                    node = Node::Rep(Box::new(node), 0, None);
                }
                b'+' => {
                    self.p += 1;
                    node = Node::Rep(Box::new(node), 1, None);
                }
                b'?' => {
                    self.p += 1;
                    node = Node::Rep(Box::new(node), 0, Some(1));
                }
                b'{' => {
                    self.p += 1;
                    let min = self.number();
                    let max = if self.peek() == b',' {
                        self.p += 1;
                        if self.peek() == b'}' {
                            None
                        } else {
                            Some(self.number())
                        }
                    } else {
                        Some(min)
                    };
                    if self.peek() == b'}' {
                        self.p += 1;
                    }
                    node = Node::Rep(Box::new(node), min, max);
                }
                _ => return node,
            }
        }
    }

    fn atom(&mut self) -> Node {
        let c = self.peek();
        match c {
            b'(' => {
                self.p += 1;
                let n = self.alt();
                if self.peek() == b')' {
                    self.p += 1;
                }
                n
            }
            b'"' | b'\'' => {
                self.p += 1;
                let ci = c == b'\'';
                let mut items = Vec::new();
                while self.p < self.s.len() && self.s[self.p] != c {
                    let mut b = self.s[self.p];
                    self.p += 1;
                    if b == b'\\' {
                        b = self.escape();
                    }
                    let mut set = ByteSet::single(b);
                    if ci && b.is_ascii_alphabetic() {
                        set.insert(b.to_ascii_lowercase());
                        set.insert(b.to_ascii_uppercase());
                    }
                    items.push(Node::Set(set));
                }
                self.p += 1;
                Node::Seq(items)
            }
            b'[' => {
                self.p += 1;
                let mut set = ByteSet::EMPTY;
                let mut prev: Option<u8> = None;
                while self.p < self.s.len() && self.s[self.p] != b']' {
                    let mut b = self.s[self.p];
                    self.p += 1;
                    if b == b'-' && prev.is_some() && self.s.get(self.p) != Some(&b']') {
                        let lo = prev.unwrap_or(0);
                        let mut hi = self.s.get(self.p).copied().unwrap_or(0);
                        self.p += 1;
                        if hi == b'\\' {
                            hi = self.escape();
                        }
                        for x in lo..=hi {
                            set.insert(x);
                        }
                        prev = None;
                        continue;
                    }
                    if b == b'\\' {
                        b = self.escape();
                    }
                    set.insert(b);
                    prev = Some(b);
                }
                self.p += 1;
                Node::Set(set)
            }
            _ => {
                let start = self.p;
                while self.p < self.s.len() && (self.s[self.p].is_ascii_alphanumeric() || self.s[self.p] == b'_') {
                    self.p += 1;
                }
                let name = std::str::from_utf8(&self.s[start..self.p]).unwrap_or("");
                if name.is_empty() {
                    // Unknown character: skip it to guarantee progress.
                    self.p += 1;
                    return Node::Seq(Vec::new());
                }
                self.defs.get(name).cloned().unwrap_or(Node::Seq(Vec::new()))
            }
        }
    }
}

/// Parses `name = expr;` definitions (C comments allowed).
pub(crate) fn parse_defs(src: &str) -> HashMap<String, Node> {
    let mut defs: HashMap<String, Node> = HashMap::new();
    let bytes = src.as_bytes();
    let mut p = 0;
    loop {
        let mut ep = ExprParser { s: bytes, p, defs: &defs };
        ep.skip_ws();
        p = ep.p;
        if p >= bytes.len() {
            break;
        }
        let start = p;
        while p < bytes.len() && (bytes[p].is_ascii_alphanumeric() || bytes[p] == b'_') {
            p += 1;
        }
        let name = src[start..p].to_string();
        while p < bytes.len() && bytes[p] != b'=' {
            p += 1;
        }
        p += 1;
        let mut ep = ExprParser { s: bytes, p, defs: &defs };
        let node = ep.alt();
        p = ep.p;
        if ep.peek() == b';' {
            p = ep.p + 1;
        }
        defs.insert(name, node);
    }
    defs
}

/// Parses a single expression in terms of `defs`.
pub(crate) fn parse_expr(src: &str, defs: &HashMap<String, Node>) -> Node {
    let mut ep = ExprParser {
        s: src.as_bytes(),
        p: 0,
        defs,
    };
    ep.alt()
}

#[derive(Debug, Clone, Copy)]
enum State {
    Byte(ByteSet, usize),
    Split(usize, usize),
    Match(u16),
}

/// A compiled multi-rule scanner.
#[derive(Debug)]
pub(crate) struct Scanner {
    states: Vec<State>,
    start: usize,
}

impl Scanner {
    /// Compiles `rules` (in priority order) into one scanner.
    pub(crate) fn new(rules: &[Node]) -> Self {
        let mut sc = Self {
            states: Vec::new(),
            start: 0,
        };
        let mut entries = Vec::new();
        for (i, r) in rules.iter().enumerate() {
            let m = sc.push(State::Match(u16::try_from(i).unwrap_or(u16::MAX)));
            entries.push(sc.compile(r, m));
        }
        let mut entry = *entries.last().unwrap_or(&0);
        for &e in entries.iter().rev().skip(1) {
            entry = sc.push(State::Split(e, entry));
        }
        sc.start = entry;
        sc
    }

    fn push(&mut self, s: State) -> usize {
        self.states.push(s);
        self.states.len() - 1
    }

    fn compile(&mut self, node: &Node, next: usize) -> usize {
        match node {
            Node::Set(set) => self.push(State::Byte(*set, next)),
            Node::Seq(items) => {
                let mut n = next;
                for it in items.iter().rev() {
                    n = self.compile(it, n);
                }
                n
            }
            Node::Alt(alts) => {
                let entries: Vec<usize> = alts.iter().map(|a| self.compile(a, next)).collect();
                let mut entry = *entries.last().unwrap_or(&next);
                for &e in entries.iter().rev().skip(1) {
                    entry = self.push(State::Split(e, entry));
                }
                entry
            }
            Node::Rep(body, min, max) => {
                let mut n = next;
                match max {
                    None => {
                        let s = self.push(State::Split(0, next));
                        let b = self.compile(body, s);
                        self.states[s] = State::Split(b, next);
                        n = s;
                    }
                    Some(max) => {
                        for _ in *min..*max {
                            let b = self.compile(body, n);
                            n = self.push(State::Split(b, n));
                        }
                    }
                }
                for _ in 0..*min {
                    n = self.compile(body, n);
                }
                n
            }
        }
    }

    fn add(&self, list: &mut Vec<usize>, marks: &mut [u32], gen: u32, s: usize, stack: &mut Vec<usize>) {
        stack.push(s);
        while let Some(s) = stack.pop() {
            if marks[s] == gen {
                continue;
            }
            marks[s] = gen;
            match self.states[s] {
                State::Split(a, b) => {
                    stack.push(b);
                    stack.push(a);
                }
                _ => list.push(s),
            }
        }
    }

    /// Longest match at `start`: `(length, rule index)`. Bytes past the end
    /// of `input` read as NUL.
    pub(crate) fn longest_match(&self, input: &[u8], start: usize) -> Option<(usize, usize)> {
        let mut marks = vec![0u32; self.states.len()];
        let mut gen = 1;
        let mut cur = Vec::new();
        let mut next = Vec::new();
        let mut stack = Vec::new();
        self.add(&mut cur, &mut marks, gen, self.start, &mut stack);
        let mut best = None;
        let mut pos = start;
        loop {
            let mut rule = None;
            for &s in &cur {
                if let State::Match(r) = self.states[s] {
                    let r = usize::from(r);
                    if rule.is_none_or(|x| r < x) {
                        rule = Some(r);
                    }
                }
            }
            if let Some(r) = rule {
                best = Some((pos - start, r));
            }
            if cur.is_empty() || pos > input.len() + 64 {
                break;
            }
            let b = input.get(pos).copied().unwrap_or(0);
            gen += 1;
            next.clear();
            for &s in &cur {
                if let State::Byte(set, n) = self.states[s] {
                    if set.contains(b) {
                        self.add(&mut next, &mut marks, gen, n, &mut stack);
                    }
                }
            }
            std::mem::swap(&mut cur, &mut next);
            pos += 1;
        }
        best
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn scanner(defs: &str, rules: &[&str]) -> Scanner {
        let d = parse_defs(defs);
        let nodes: Vec<Node> = rules.iter().map(|r| parse_expr(r, &d)).collect();
        Scanner::new(&nodes)
    }

    #[test]
    fn longest_then_first() {
        let sc = scanner(
            "digit = [0-9]; word = 'abc'; num = digit+;",
            &["word", "num", "digit digit", "[a-z]+"],
        );
        assert_eq!(sc.longest_match(b"ABC", 0), Some((3, 0)));
        assert_eq!(sc.longest_match(b"abcd", 0), Some((4, 3)));
        assert_eq!(sc.longest_match(b"12", 0), Some((2, 1)));
        assert_eq!(sc.longest_match(b"x12", 1), Some((2, 1)));
        assert_eq!(sc.longest_match(b"!", 0), None);
    }

    #[test]
    fn repeats_and_escapes() {
        let sc = scanner("y = [0-9]{2,4}; z = \"\\000\" | [\\t ]+;", &["y", "z"]);
        assert_eq!(sc.longest_match(b"12345", 0), Some((4, 0)));
        assert_eq!(sc.longest_match(b"1", 0), None);
        assert_eq!(sc.longest_match(b"", 0), Some((1, 1)));
        assert_eq!(sc.longest_match(b"\t  x", 0), Some((3, 1)));
    }

    #[test]
    fn comments_and_classes() {
        let sc = scanner("/* c */ a = [+-]? \"x\" /* inner */; b = [.\\t-];", &["a", "b"]);
        assert_eq!(sc.longest_match(b"-x", 0), Some((2, 0)));
        assert_eq!(sc.longest_match(b"-", 0), Some((1, 1)));
        assert_eq!(sc.longest_match(b"\t", 0), Some((1, 1)));
    }
}
